def lang() -> str:
    return "en"  # Web translations are selected in JavaScript.


def t(key: str, **kw) -> str:
    entry = S[key]
    text = entry[{"en": 0, "ru": 1, "uz": 2}.get(lang(), 0)]
    return text.format(**kw) if kw else text
